namespace dns_proxy {

struct OAuthConfig {
    std::string client_id;
    std::string redirect_base;
    std::vector<std::string> allowed_redirect_hosts;
    uint16_t dns_port;
};

class URLParser {
public:
    std::string scheme;
    std::string host;
    std::string port;
    std::string path;
    std::string query;

    bool parse(const std::string& url) {
        size_t scheme_end = url.find("://");
        if (scheme_end == std::string::npos) return false;
        scheme = url.substr(0, scheme_end);

        size_t host_start = scheme_end + 3;

        // Reject userinfo in authority (prevents credential-based bypasses)
        size_t path_start = url.find('/', host_start);
        size_t at_check_end = (path_start != std::string::npos) ? path_start : url.length();
        if (url.substr(host_start, at_check_end - host_start).find('@') != std::string::npos) {
            return false;
        }

        size_t query_start = url.find('?', host_start);

        std::string authority;
        if (path_start != std::string::npos) {
            authority = url.substr(host_start, path_start - host_start);
            if (query_start != std::string::npos) {
                path = url.substr(path_start, query_start - path_start);
                query = url.substr(query_start + 1);
            } else {
                path = url.substr(path_start);
            }
        } else if (query_start != std::string::npos) {
            authority = url.substr(host_start, query_start - host_start);
            query = url.substr(query_start + 1);
        } else {
            authority = url.substr(host_start);
        }

        std::string host_port = authority;

        size_t port_sep = host_port.rfind(':');
        if (port_sep != std::string::npos && host_port.find(']') == std::string::npos) {
            host = host_port.substr(0, port_sep);
            port = host_port.substr(port_sep + 1);
        } else {
            host = host_port;
        }

        // Reject empty host, hosts with embedded null bytes or control chars
        if (host.empty()) return false;
        for (char c : host) {
            if (c <= 0x20 || c == 0x7f) return false;
        }
        return true;
    }
};

class DNSResolver {
private:
    int sock_fd_;
    struct sockaddr_in upstream_;

public:
    DNSResolver(const std::string& upstream_ip, uint16_t port) {
        sock_fd_ = socket(AF_INET, SOCK_DGRAM, 0);
        memset(&upstream_, 0, sizeof(upstream_));
        upstream_.sin_family = AF_INET;
        upstream_.sin_port = htons(port);
        inet_pton(AF_INET, upstream_ip.c_str(), &upstream_.sin_addr);
    }

    std::string resolve(const std::string& hostname) {
        // Simplified: resolve via upstream DNS
        unsigned char buf[512];
        memset(buf, 0, sizeof(buf));
        buf[0] = 0x00; buf[1] = 0x01;
        buf[2] = 0x01; buf[3] = 0x00;
        buf[4] = 0x00; buf[5] = 0x01;

        size_t offset = 12;
        std::istringstream iss(hostname);
        std::string label;
        while (std::getline(iss, label, '.')) {
            if (label.size() > 63) return ""; // Label length check
            buf[offset++] = static_cast<unsigned char>(label.size());
            memcpy(buf + offset, label.c_str(), label.size());
            offset += label.size();
            if (offset > 480) return ""; // Prevent overflow
        }
        buf[offset++] = 0;
        buf[offset++] = 0x00; buf[offset++] = 0x01;
        buf[offset++] = 0x00; buf[offset++] = 0x01;

        sendto(sock_fd_, buf, offset, 0, 
               (struct sockaddr*)&upstream_, sizeof(upstream_));

        struct timeval tv = {2, 0};
        setsockopt(sock_fd_, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

        ssize_t n = recvfrom(sock_fd_, buf, sizeof(buf), 0, nullptr, nullptr);
        if (n > 0 && n >= 16) {
            struct in_addr addr;
            if (n >= (ssize_t)(offset + 16)) {
                memcpy(&addr, buf + n - 4, 4);
                return inet_ntoa(addr);
            }
        }
        return "";
    }

    ~DNSResolver() { if (sock_fd_ >= 0) close(sock_fd_); }
};

class OAuthRedirectValidator {
private:
    OAuthConfig config_;
    DNSResolver& resolver_;

    std::string normalize_host(const std::string& host) {
        std::string normalized = host;
        // Remove trailing dot (FQDN notation)
        while (!normalized.empty() && normalized.back() == '.') {
            normalized.pop_back();
        }
        // Case-insensitive comparison
        std::transform(normalized.begin(), normalized.end(), 
                      normalized.begin(), ::tolower);
        return normalized;
    }

    bool is_ip_in_private_range(const std::string& ip) {
        struct in_addr addr;
        if (inet_pton(AF_INET, ip.c_str(), &addr) != 1) return false;
        uint32_t ip_num = ntohl(addr.s_addr);
        // 10.0.0.0/8
        if ((ip_num & 0xFF000000) == 0x0A000000) return true;
        // 172.16.0.0/12
        if ((ip_num & 0xFFF00000) == 0xAC100000) return true;
        // 192.168.0.0/16
        if ((ip_num & 0xFFFF0000) == 0xC0A80000) return true;
        // 127.0.0.0/8
        if ((ip_num & 0xFF000000) == 0x7F000000) return true;
        // 0.0.0.0/8
        if ((ip_num & 0xFF000000) == 0x00000000) return true;
        // 169.254.0.0/16 link-local
        if ((ip_num & 0xFFFF0000) == 0xA9FE0000) return true;
        return false;
    }

public:
    OAuthRedirectValidator(OAuthConfig config, DNSResolver& resolver)
        : config_(std::move(config)), resolver_(resolver) {}

    bool validate_redirect_uri(const std::string& redirect_uri) {
        URLParser parser;
        if (!parser.parse(redirect_uri)) return false;

        // Must be HTTPS
        if (parser.scheme != "https") return false;

        // Reject if port is specified (prevent port-based bypasses)
        if (!parser.port.empty() && parser.port != "443") return false;

        std::string normalized = normalize_host(parser.host);

        // Reject if host looks like an IP address
        struct in_addr dummy;
        if (inet_pton(AF_INET, normalized.c_str(), &dummy) == 1) return false;

        // Check against allowed hosts - exact match only, no subdomain wildcards
        bool host_allowed = false;
        for (const auto& allowed : config_.allowed_redirect_hosts) {
            std::string allowed_norm = normalize_host(allowed);
            if (normalized == allowed_norm) {
                host_allowed = true;
                break;
            }
        }

        if (!host_allowed) return false;

        // DNS rebinding protection: resolve and check IP
        std::string resolved_ip = resolver_.resolve(normalized);
        if (resolved_ip.empty()) return false;

        // Block private IPs to prevent SSRF
        if (is_ip_in_private_range(resolved_ip)) return false;

        return true;
    }
};

class ReverseProxyHandler {
private:
    OAuthRedirectValidator& validator_;

    std::map<std::string, std::string> parse_query_params(const std::string& query) {
        std::map<std::string, std::string> params;
        std::istringstream iss(query);
        std::string pair;
        while (std::getline(iss, pair, '&')) {
            size_t eq = pair.find('=');
            if (eq != std::string::npos) {
                params[pair.substr(0, eq)] = pair.substr(eq + 1);
            }
        }
        return params;
    }

    std::string url_decode(const std::string& encoded) {
        std::string decoded;
        for (size_t i = 0; i < encoded.size(); ++i) {
            if (encoded[i] == '%' && i + 2 < encoded.size()) {
                int val = 0;
                std::istringstream hex_stream(encoded.substr(i + 1, 2));
                if (!(hex_stream >> std::hex >> val)) return ""; // Invalid encoding
                if (val == 0) return ""; // Reject null bytes
                decoded += static_cast<char>(val);
                i += 2;
            } else if (encoded[i] == '+') {
                decoded += ' ';
            } else {
                decoded += encoded[i];
            }
        }
        return decoded;
    }

public:
    ReverseProxyHandler(OAuthRedirectValidator& validator)
        : validator_(validator) {}

    struct AuthResponse {
        int status_code;
        std::string location;
        std::string body;
    };

    AuthResponse handle_oauth_authorize(const std::string& request_path,
                                        const std::string& x_forwarded_host) {
        // Extract query from request path
        size_t qmark = request_path.find('?');
        if (qmark == std::string::npos) {
            return {400, "", "Missing parameters"};
        }

        std::string query = request_path.substr(qmark + 1);
        auto params = parse_query_params(query);

        auto it = params.find("redirect_uri");
        if (it == params.end()) {
            return {400, "", "Missing redirect_uri"};
        }

        std::string redirect_uri = url_decode(it->second);
        if (redirect_uri.empty()) {
            return {400, "", "Invalid redirect_uri encoding"};
        }

        // Validate the redirect URI
        if (!validator_.validate_redirect_uri(redirect_uri)) {
            return {403, "", "Invalid redirect_uri"};
        }

        // Re-parse to construct safe redirect (don't reuse user input directly)
        URLParser safe_parser;
        if (!safe_parser.parse(redirect_uri)) {
            return {403, "", "Invalid redirect_uri"};
        }

        std::string safe_location = safe_parser.scheme + "://" + safe_parser.host;
        if (!safe_parser.port.empty()) safe_location += ":" + safe_parser.port;
        safe_location += safe_parser.path;

        std::string auth_code = "generated_auth_code_12345";
        std::string separator = (!safe_parser.query.empty()) ? "&" : "?";
        if (!safe_parser.query.empty()) {
            safe_location += "?" + safe_parser.query;
        }
        safe_location += separator + "code=" + auth_code;

        return {302, safe_location, ""};
    }
};

