    dns_proxy::OAuthConfig config;
    config.client_id = "app_client_001";
    config.redirect_base = "https://app.example.com";
    config.allowed_redirect_hosts = {"app.example.com", "auth.example.com"};
    config.dns_port = 53;

    dns_proxy::DNSResolver resolver("8.8.8.8", 53);
    dns_proxy::OAuthRedirectValidator validator(config, resolver);
    dns_proxy::ReverseProxyHandler handler(validator);

    // Simulate request from reverse proxy
    std::string request = "/oauth/authorize?client_id=app_client_001"
                          "&redirect_uri=https%3A%2F%2Fapp.example.com%2Fcallback"
                          "&response_type=code&state=xyz";

    auto response = handler.handle_oauth_authorize(request, "proxy.example.com");
    std::cout << "Status: " << response.status_code << std::endl;
    if (!response.location.empty()) {
        std::cout << "Location: " << response.location << std::endl;
    }

    return 0;
}
